import React from 'react';
import PropTypes from 'prop-types';

/**
 * ClinicalRecommendationCard
 *
 * Displays structured, actionable clinical recommendations generated by the LLM
 * based on the vision model inference outputs (ViT classification, YOLO detection,
 * ResNet50 U-Net lesion burden coverage) and clinical reasoning.
 */
export default function ClinicalRecommendationCard({ recommendation, loading = false, className = '' }) {
  if (loading) {
    return (
      <div
        className={`rounded-xl border border-outline-variant/20 bg-surface-container-low/95 backdrop-blur-sm p-4 md:p-5 space-y-4 shadow-card-subtle animate-pulse flex flex-col ${className}`}
        data-testid="clinical-recommendation-skeleton"
      >
        <div className="flex items-center justify-between pb-3 border-b border-outline-variant/15">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-primary/10 border border-primary/20" />
            <div className="h-3.5 w-40 bg-surface-container-highest rounded" />
          </div>
          <div className="h-5 w-24 bg-surface-container-highest rounded-full" />
        </div>
        <div className="space-y-2">
          <div className="h-3 w-48 bg-surface-container-highest rounded" />
          <div className="h-2.5 w-full bg-surface-container-highest/60 rounded" />
          <div className="h-2.5 w-5/6 bg-surface-container-highest/60 rounded" />
        </div>
      </div>
    );
  }

  if (!recommendation) return null;

  const {
    triage_level = 'Routine',
    biosecurity_protocol = [],
    clinical_monitoring = [],
    treatment_considerations = null,
  } = recommendation;

  const triageLower = (triage_level || '').toLowerCase();
  const isEmergency = triageLower.includes('emergency');
  const isUrgent = triageLower.includes('urgent');
  const isPriority = triageLower.includes('priority');

  const triageBadgeStyle = isEmergency
    ? 'bg-rose-500/20 text-rose-300 border-rose-500/40'
    : isUrgent
    ? 'bg-red-500/20 text-red-300 border-red-500/40'
    : isPriority
    ? 'bg-amber-500/20 text-amber-300 border-amber-500/40'
    : 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40';

  const triageIcon = isEmergency
    ? 'emergency'
    : isUrgent
    ? 'warning'
    : isPriority
    ? 'priority_high'
    : 'check_circle';

  return (
    <div
      className={`rounded-xl border border-outline-variant/20 bg-surface-container-low/95 backdrop-blur-sm p-4 md:p-5 space-y-4 shadow-card-subtle transition-all duration-300 flex flex-col ${className}`}
      data-testid="clinical-recommendation-card"
    >
      {/* Card Header with Triage Level */}
      <div className="flex flex-wrap items-center justify-between gap-2.5 pb-3 border-b border-outline-variant/15">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-primary/10 border border-primary/20 text-primary">
            <span className="material-symbols-outlined text-base">medical_services</span>
          </div>
          <div>
            <h4 className="text-xs font-bold text-on-surface uppercase tracking-wider font-mono">
              Clinical Recommendations
            </h4>
            <p className="text-[10px] text-outline font-mono">LLM DECISION SUPPORT</p>
          </div>
        </div>

        {/* Triage Level Badge */}
        <div
          className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-2xs font-mono font-bold border ${triageBadgeStyle}`}
          data-testid="recommendation-triage-level"
        >
          <span className="material-symbols-outlined text-xs">{triageIcon}</span>
          <span>Triage: {triage_level}</span>
        </div>
      </div>

      {/* Biosecurity & Quarantine Protocol */}
      {biosecurity_protocol.length > 0 && (
        <div className="space-y-2">
          <div className="flex items-center gap-1.5 text-xs font-bold text-on-surface">
            <span className="material-symbols-outlined text-xs text-rose-400">shield</span>
            <span>Biosecurity &amp; Quarantine Protocol</span>
          </div>
          <ul
            className="space-y-1.5 pl-1 text-2xs md:text-xs text-on-surface-variant leading-relaxed"
            data-testid="biosecurity-protocol-list"
          >
            {biosecurity_protocol.map((step, idx) => (
              <li key={idx} className="flex items-start gap-2">
                <span className="material-symbols-outlined text-primary text-xs shrink-0 mt-0.5" style={{ fontVariationSettings: "'FILL' 1" }}>
                  check_circle
                </span>
                <span>{step}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Clinical Monitoring & Surveillance */}
      {clinical_monitoring.length > 0 && (
        <div className="space-y-2 pt-1 border-t border-outline-variant/10">
          <div className="flex items-center gap-1.5 text-xs font-bold text-on-surface">
            <span className="material-symbols-outlined text-xs text-amber-400">visibility</span>
            <span>Clinical Monitoring &amp; Surveillance</span>
          </div>
          <ul
            className="space-y-1.5 pl-1 text-2xs md:text-xs text-on-surface-variant leading-relaxed"
            data-testid="clinical-monitoring-list"
          >
            {clinical_monitoring.map((step, idx) => (
              <li key={idx} className="flex items-start gap-2">
                <span className="material-symbols-outlined text-amber-400 text-xs shrink-0 mt-0.5">
                  arrow_forward
                </span>
                <span>{step}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Treatment Considerations (if present) */}
      {treatment_considerations && (
        <div className="p-2.5 rounded-lg bg-surface-container border border-outline-variant/15 text-2xs text-on-surface-variant leading-relaxed">
          <div className="flex items-center gap-1.5 text-2xs font-bold text-primary mb-1">
            <span className="material-symbols-outlined text-xs">medication</span>
            <span>Therapeutic &amp; Supportive Considerations</span>
          </div>
          <p>{treatment_considerations}</p>
        </div>
      )}

      {/* Footnote Disclaimer */}
      <div className="flex items-center gap-1.5 pt-2 border-t border-outline-variant/10 text-[10px] text-outline font-sans mt-auto">
        <span className="material-symbols-outlined text-xs shrink-0">info</span>
        <span>Decision support only. Clinical actions must be authorized by a licensed veterinary professional.</span>
      </div>
    </div>
  );
}

ClinicalRecommendationCard.propTypes = {
  recommendation: PropTypes.shape({
    triage_level: PropTypes.string,
    biosecurity_protocol: PropTypes.arrayOf(PropTypes.string),
    clinical_monitoring: PropTypes.arrayOf(PropTypes.string),
    treatment_considerations: PropTypes.string,
  }),
  className: PropTypes.string,
};
